              <span className="tournament-score">
                {score
                  ? `${score.moves} moves · ${time}`
                  : 'Moves: — · Time: —'}
              </span>
            </li>
          );
        })}
      </ul>
      <p className={match.winner === null ? 'help' : 'tournament-winner'}>
        Winner: {match.winner === null ? 'To be decided' : tournament.players[match.winner]}
      </p>
    </article>
  );
}
